import React, { useState, useContext } from "react";
import { GlobalContext } from "../context/GlobalState";
import styled, { keyframes } from "styled-components";

const fadeIn = keyframes`
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
`;

const pulse = keyframes`
  0% {
    box-shadow: 0 0 0 0 rgba(74, 124, 255, 0.4);
  }
  70% {
    box-shadow: 0 0 0 10px rgba(74, 124, 255, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(74, 124, 255, 0);
  }
`;

const Container = styled.div`
  background: #ffffff;
  border-radius: 12px;
  padding: 1.5rem;
  margin: 1rem 0;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);
  animation: ${fadeIn} 0.6s ease-out;
  transition: all 0.3s ease;

  &:hover {
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.15);
  }
`;

const Title = styled.h3`
  color: #2c3e50;
  margin-bottom: 1.5rem;
  font-size: 1.4rem;
  position: relative;
  padding-bottom: 0.5rem;

  &::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 0;
    width: 50px;
    height: 3px;
    background: linear-gradient(90deg, #4a7cff, #4ad2ff);
    border-radius: 3px;
  }
`;

const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
`;

const Input = styled.input`
  padding: 0.8rem 1rem;
  border: 2px solid #e0e0e0;
  border-radius: 8px;
  font-size: 1rem;
  transition: all 0.3s ease;
  outline: none;

  &:focus {
    border-color: #4a7cff;
    box-shadow: 0 0 0 3px rgba(74, 124, 255, 0.2);
  }

  &::placeholder {
    color: #b0b0b0;
  }
`;

const Button = styled.button`
  background: linear-gradient(135deg, #4a7cff, #4ad2ff);
  color: white;
  border: none;
  padding: 0.8rem;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  animation: ${pulse} 2s infinite;

  &:hover {
    background: linear-gradient(135deg, #3a6bef, #3ac2ef);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(74, 124, 255, 0.3);
  }

  &:active {
    transform: translateY(0);
  }

  &:disabled {
    background: #cccccc;
    cursor: not-allowed;
    animation: none;
  }
`;

const AddTransaction = () => {
  const { addTransaction } = useContext(GlobalContext);
  const [text, setText] = useState("");
  const [amount, setAmount] = useState("");

  const onSubmit = (e) => {
    e.preventDefault();

    if (!text || !amount) {
      alert("Please enter text and amount!");
      return;
    }

    const newTransaction = {
      id: Math.floor(Math.random() * 100000),
      text,
      amount: +amount, // Convert to number
    };

    addTransaction(newTransaction);

    // Clear input fields
    setText("");
    setAmount("");
  };

  return (
    <Container>
      <Title>Add New Transaction</Title>
      <Form onSubmit={onSubmit}>
        <Input
          type="text"
          placeholder="Enter description..."
          value={text}
          onChange={(e) => setText(e.target.value)}
        />
        <Input
          type="number"
          placeholder="Enter amount (positive for income, negative for expense)"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
        />
        <Button type="submit" disabled={!text || !amount}>
          Add Transaction
        </Button>
      </Form>
    </Container>
  );
};

export default AddTransaction;
